def publish_with_backoff(self, event, max_retries: int = 4) -> int:
        for attempt in range(max_retries):
            seq = self.try_publish(event)
            if seq is not None:
                return seq
            time.sleep((0.001 * (2 ** attempt)) + random.uniform(0, 0.0005))
        raise BufferError('Ring buffer saturated after bounded retries')
